function getCiscoAiTranslation(key, lang) {
    if (ciscoaiTranslations[lang] && ciscoaiTranslations[lang][key]) {
        return ciscoaiTranslations[lang][key];
    }
    if (ciscoaiTranslations.en && ciscoaiTranslations.en[key]) {
        return ciscoaiTranslations.en[key];
    }
    return null;
}

function applyCiscoAiTranslations(lang) {
    console.log('Applying cisco-ai translations for:', lang);
    let count = 0;
    document.querySelectorAll('[data-i18n]').forEach(element => {
        const key = element.getAttribute('data-i18n');
        if (key && key.startsWith('review.cisco-ai.')) {
            const translation = getCiscoAiTranslation(key, lang);
            if (translation) {
                element.textContent = translation;
                count++;
            }
        }
    });
    console.log(`Applied ${count} cisco-ai translations`);
}

window.addEventListener('languageChanged', (e) => {
    const lang = e.detail.language;
    setTimeout(() => applyCiscoAiTranslations(lang), 200);
});

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
        const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
        applyCiscoAiTranslations(currentLang);
    });
} else {
    const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
    applyCiscoAiTranslations(currentLang);
}

console.log('cisco-ai i18n loaded');
